const GraphTimeout = 5 * time.Minute

// stderrTailBytes bounds how much of a failing task's output is echoed into
// the error message.
const stderrTailBytes = 2048

// graphTask is the task name the CLI delegates to. It is the contract the
// scaffolded Taskfile satisfies: run it in the host directory and it prints
