const graphTask = "graph"

// taskfileNames are the filenames Task looks for, in its search order.
var taskfileNames = []string{"Taskfile.yml", "Taskfile.yaml"}

// ContractError reports a host directory that does not satisfy the graph
// task contract: no Taskfile, or no "graph" task in it. It is a setup
// problem, distinct from a task that ran and failed, so callers can route
// the developer to their own Taskfile rather than to the tooling.
type ContractError struct {
	HostDir string
	Problem string
}

func (e *ContractError) Error() string {
	return fmt.Sprintf("%s: %s\nadd a Taskfile with a 'graph' task — see the sample Taskfiles shipped with the template library", e.HostDir, e.Problem)
}

// RunGraph executes the host directory's graph task and decodes its stdout.
//
// The CLI owns the contract, not the process: what the task does to produce
// the record — build flags, codegen, anything else — is the Taskfile's
// business, and this function must not grow opinions about it. --silent
// keeps Task's own command echo off stdout so the record stays the only
// thing Decode sees.
//
// Callers should say what they are doing before calling: on a cold project
// this can take minutes, and a silent wait that long reads as a hang.
func RunGraph(ctx context.Context, runner command.Runner, hostDir string) (*Topology, error) {
	if err := checkGraphContract(hostDir); err != nil {
		return nil, err
	}

	ctx, cancel := context.WithTimeout(ctx, GraphTimeout)
	defer cancel()

	stdout, stderr, err := runner.Run(ctx, hostDir, "task", "--silent", graphTask)
	if err != nil {
		// The binary itself missing is an environment problem; the runner's
		// NotInstalledError already says how to fix it.
		if errors.Is(err, command.ErrNotInstalled) {
			return nil, err
		}
		return nil, fmt.Errorf("graph task failed: %w", withTail(err, stderr))
	}
	t, err := Decode(bytesReader(stdout))
	if err != nil {
		// The stdout tail is the evidence: a decode failure means the task
		// printed something other than the record.
		return nil, fmt.Errorf("%w%s", err, tail(stdout))
	}
	return t, nil
}

// checkGraphContract verifies the host directory can answer the graph task
// before paying for a subprocess: the Taskfile must exist and declare a
// "graph" task. Line-prefix matching on "graph:" is deliberately naive — a
// stricter YAML parse would have to replicate Task's include and merge
// semantics to be correct, and a false negative here only costs the run the
// file already said it cannot serve.
func checkGraphContract(hostDir string) error {
	var content []byte
