// given name. YAML task names are keys under "tasks:", so a line whose first
// token is the name followed by a colon is a declaration; an alias-only
// reference is not, which is correct — the contract needs the task itself.
func declaresTask(content []byte, name string) bool {
	for line := range lines(content) {
		trimmed := trimLeftSpaces(line)
		if len(trimmed) > len(name)+1 && string(trimmed[:len(name)+1]) == name+":" {
			return true
		}
	}
	return false
}

// withTail attaches the last stderrTailBytes of a stream to an error,
// matching the evidence shape the dotnet invocation produced.
func withTail(err error, stderr []byte) error {
	if s := tail(stderr); s != "" {
		return fmt.Errorf("%w%s", err, s)
	}
	return err
}

